def transform(grid):
    from collections import Counter
    counts = Counter(x for row in grid for x in row)
    bg = counts.most_common(1)[0][0]
    fg = max((x for x in counts if x != bg), key=lambda x: counts[x])
    pts = [(r, c) for r in range(len(grid)) for c in range(len(grid[0])) if grid[r][c] == fg]
    if not pts:
        return [row[:] for row in grid]

    r0, r1 = min(r for r, c in pts), max(r for r, c in pts)
    c0, c1 = min(c for r, c in pts), max(c for r, c in pts)
    out = [row[:] for row in grid]
    for c in range(c0, c1 + 1):
        for r in (r0, r1):
            if out[r][c] == bg:
                out[r][c] = 2
    for r in range(r0, r1 + 1):
        for c in (c0, c1):
            if out[r][c] == bg:
                out[r][c] = 2
    return out
